unsigned char pool[2048]; int plen;
typedef struct { int off; int len; } SYM;  // off into pool
int S[512];       // symbol index array for current word
SYM TBL[2048];   // symbol table: sym id -> bytes (off,len)
int svid[2048];  // sym id -> vocab id

// reset per word:
plen=0;
for each byte b in word: TBL[n].off=plen; TBL[n].len=1; pool[plen]=b; plen++; svid[n]=b; S[i]=n; i++;
```

