  for (int r=0;r<NM;r++) {
    int o=MO[r], l1=ML1[r], l2=ML2[r];
    for (int i=0;i<ns-1;i++) {
      if (TBL[S[i]].len==l1 && TBL[S[i+1]].len==l2 &&
          memcmp(pool+TBL[S[i]].off, MB+o, l1)==0 &&
          memcmp(pool+TBL[S[i+1]].off, MB+o+l1, l2)==0) {
