        int nid=ns;
        TBL[nid].off=plen; TBL[nid].len=l1+l2;
        memcpy(pool+plen, pool+TBL[S[i]].off, l1);
        memcpy(pool+plen+l1, pool+TBL[S[i+1]].off, l2);
