static int bpe_word(const unsigned char *wb, int nw, int *out) {
    plen = 0;
    int n = 0, nc = 0;
    for (int i = 0; i < nw; i++) {
        tb[nc].o = plen; tb[nc].n = 1;
        pool[plen] = wb[i]; plen++;
        sv[nc] = wb[i]; S[n] = nc; nc++; n++;
    }
again:
    for (int r = 0; r < NM; r++) {
