        for (int i = 0; i < n - 1; i++) {
            if (tb[S[i]].n == l1 && tb[S[i + 1]].n == l2 &&
                !memcmp(pool + tb[S[i]].o, MB + o, l1) &&
                !memcmp(pool + tb[S[i + 1]].o, MB + o + l1, l2)) {
                int newid = nc;
                tb[newid].o = plen; tb[newid].n = l1 + l2;
                memcpy(pool + plen, pool + tb[S[i]].o, l1);
                memcpy(pool + plen + l1, pool + tb[S[i + 1]].o, l2);
                plen += l1 + l2;
                sv[newid] = 256 + r;
                nc++;
                int ns2 = 0;
                for (int j2 = 0; j2 < i; j2++) S2[ns2++] = S[j2];
                S2[ns2++] = newid;
                for (int j2 = i + 2; j2 < n; j2++) S2[ns2++] = S[j2];
                memcpy(S, S2, ns2 * sizeof(int));
                n = ns2;
                goto again;
            }
        }
    }
    for (int i = 0; i < n; i++) out[i] = sv[S[i]];
    return n;
}
```

This fixes the symbol index collision: newid = nc (monotonic). Note n (word length) decreases; nc keeps increasing.

